--[[ generated by midnight from midnight/resurrect/ui.mn, edit that instead ]] local _MODULE = {} function _MODULE.choose_session(choices, cb)
  local u = require("resurrect/util")
  vim.ui.select(choices, {
  prompt = "Found Sessions", 
  format_item = function(s) return tostring(u.session_shortname(s.name)) .. " (" .. tostring(#(s.files or {})) .. " files)" end
  }, cb)
end

--- a floating y/n prompt. opts.callback(answer) gets true for y/Y, false for
--- n/N/q/<Esc>, and opts.default (false if unset) for <CR> or leaving the
--- window some other way (<C-w>w, :q, a click)
function _MODULE.confirmation(opts)
  local prompt = opts.prompt or "? [y/N]"
  local default = opts.default or false

  local width = math.min(vim.fn.strdisplaywidth(prompt) + 4, vim.o.columns - 2)
  local height = 3
  local pad = string.rep(" ", width)

  local buf = vim.api.nvim_create_buf(false, true)
  vim.api.nvim_buf_set_lines(buf, 0, -1, false, {pad, "  " .. tostring(prompt), pad})
  vim.bo[buf].modifiable = false
  vim.bo[buf].bufhidden = "wipe"

  local win = vim.api.nvim_open_win(buf, true, {
  relative = "editor", 
  width = width, 
  height = height, 
  row = math.floor((vim.o.lines - height) / 2), 
  col = math.floor((vim.o.columns - width) / 2), 
  style = "minimal", 
  border = "rounded", 
  title = " Confirm ", 
  title_pos = "center"
  })

  local answered = false
  local function answer(yes)
    if answered then return end
    answered = true
    if vim.api.nvim_win_is_valid(win) then vim.api.nvim_win_close(win, true) end
    if opts.callback then opts.callback(yes) end
  end


  local keys = {
  y = true, 
  Y = true, 
  n = false, 
  N = false, 
  q = false, [
  "<Esc>"] = false, [
  "<CR>"] = default
  }
  for key, yes in pairs(keys) do
    vim.keymap.set("n", key, function() return answer(yes) end, {buffer = buf, silent = true, nowait = true})
  end

  vim.api.nvim_create_autocmd("WinLeave", {
  buffer = buf, 
  once = true, 
  callback = function() return vim.schedule(function() return answer(default) end) end
  })
end
return _MODULE
